params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$expected=[ordered]@{
  'fix/bridge-secret-channel-20260929'='c35b1bbbfb03bdfc464cef5f154ab7f5284ccaf5'
  'fix/credential-safe-secret-input-20260929'='389334a8bbcddfaa9ea8802b128824097a826854'
  'fix/heaven-secret-input-20260929'='dc0a8a2e08fad40d49fce1466e215679a7b378ca'
  'fix/issue-118-secret-input-20260929'='e4eea8eab200ac359a0a897c6733cb4832f796b5'
}
git -C $repo fetch origin --prune
$deleted=@(); $skipped=@()
foreach($b in $expected.Keys){
  $line=(git -C $repo ls-remote origin "refs/heads/$b")
  if(-not $line){$skipped += [pscustomobject]@{branch=$b;reason='already-absent'}; continue}
  $actual=(($line.Trim()) -split '\s+')[0]
  if($actual -ne $expected[$b]){$skipped += [pscustomobject]@{branch=$b;reason='tip-moved';expected=$expected[$b];actual=$actual}; continue}
  git -C $repo push origin --delete $b
  if($LASTEXITCODE -ne 0){throw "delete failed for $b"}
  $deleted += $b
}
git -C $repo fetch origin --prune
$remaining=@(git -C $repo for-each-ref --format='%(refname:short) %(objectname)' refs/remotes/origin | Where-Object {$_ -notmatch '^origin/HEAD '})
[pscustomobject]@{deleted=$deleted;skipped=$skipped;remaining=$remaining}|ConvertTo-Json -Depth 6
